$g=[IO.File]::ReadAllText($(if($env:MK_SRC){$env:MK_SRC}else{'C:\claudecode\dark raiders\dark_raiders.html'}))
function L([string]$rx){ $m=[regex]::Matches($g,$rx); if($m.Count -ne 1){ throw "anchor $rx matched $($m.Count)" }; return $m[0].Value.Replace("`r",'') }
$a1=L "  if\(G&&G\.bagOpen&&!G\.over\) return;"
$r1="  if(G&&(G.bagOpen||G.wheel)&&!G.over) return;   // v28.xx (cw-wheelnolegend): the item wheel hides the controls list too (critic on screen 61: the list ran over the wheel)"
$chk=@'
  {v:'VER',what:'the controls list is not drawn while the item wheel is open (critic: it ran over the wheel)',
   run:function(){
     if(typeof drawLegend!=='function') return 'SKIP: no drawLegend';
     var PR=CanvasRenderingContext2D.prototype, of=PR.fillText, g=null, n0=0, n1=0;
     try{
       __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       g=__state(); if(!g||!g.player) return 'SKIP: no raid';
       g.legendOn=1; g.wheel=null;
       PR.fillText=function(){ n0++; return of.apply(this,arguments); };
       drawLegend(1);
       PR.fillText=of;
       if(n0<4) return 'SKIP: the controls list did not draw with no wheel ('+n0+' texts)';
       g.wheel={t:0,list:[],sel:-1,mx:0,my:0,ox:0,oy:0,armed:0,d:0};
       PR.fillText=function(){ n1++; return of.apply(this,arguments); };
       drawLegend(1);
       PR.fillText=of;
       if(n1>0) return 'the controls list drew '+n1+' texts over the open item wheel';
       return null;
     } finally {
       PR.fillText=of;
       try{ if(g) g.wheel=null; }catch(_e){}
       try{ __endRaid('abandon'); }catch(_e){}
       __topClear();
     } }},
'@.Replace("`r",'')
$d=[ordered]@{
  title='THE ITEM WHEEL HIDES THE CONTROLS LIST'
  why='Critic on the item wheel screen: the controls list ran over the wheel. The list already steps aside for the backpack; it now steps aside for the wheel too.'
  now='The controls list is hidden while the item wheel is open.'
  edits=@( [ordered]@{ anchor=$a1; replacement=$r1 } )
  check=$chk
}
[IO.File]::WriteAllText('C:\claudecode\dark raiders\tools\handoff\drafts\draft-cw-wheelnolegend.json',($d | ConvertTo-Json -Depth 6),(New-Object Text.UTF8Encoding $false))
'written'
